<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Application\TokenGranter;

use Override;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\OAuthTokenException;

class ResolverForClientCredentials implements TokenGranterStrategy
{
    #[Override]
    public function canHandle(string $grantType, array $params): bool
    {
        return 'client_credentials' === $grantType;
    }

    #[Override]
    public function authenticate(string $tenant, AuthenticationRequest $client, array $params): AuthenticationResult
    {
        $requestedScopes = preg_split('/\s+/', trim((string) ($params['scope'] ?? ''))) ?: [];
        $requestedScopes = array_values(array_filter($requestedScopes, static fn (string $value): bool => $value !== ''));
        $allowedScopes = $client->client->allowedScopesM2m;

        if ($requestedScopes === []) {
            $grantedScopes = $allowedScopes;
        } else {
            $grantedScopes = array_values(array_intersect($requestedScopes, $allowedScopes));
            if ($grantedScopes === []) {
                throw OAuthTokenException::invalidScope('No requested scope is allowed for this client');
            }
        }

        return new AuthenticationResult(
            valid: true,
            id: $client->client->id,
            tenant: $tenant,
            scope: implode(' ', $grantedScopes),
            roles: [],
            groups: []
        );
    }
}
